  ddaFor(id) {
    const k = this.d.dda || 0, c = CHARACTERS[id];
    if (!c || Math.abs(k) < .005) return {};
    const s = c.stats;
    return { stats: { hp: s.hp * (1 + k * .8), atk: s.atk * (1 + k * .5), stun: s.stun * (1 + k * .5) }, aiBoost: k };
  }
