    this.drawCameos(w, cam);
    this.fr.drawAll(w, m, cam, { dt: 1 / 60 });
    drawProps(w, m, cam);
    this.ar.drawFront(w, cam);
    drawSpecialFront(w, m, cam);
    this.fx.draw(w, cam);
    const h = this.human;
    this.ar.drawLights(w, cam, h ? h.x : null);
